package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.view.View;import android.widget.*;import java.util.*;
/** Selective archive printing; the encrypted archive is read only. */
public final class ArchivePrintActivity extends Activity {private BatchStore store;private Spinner batches;private ListView list;private ArrayList<String[]> cards=new ArrayList<>();private CardTemplate template;private TextView status;@Override public void onCreate(Bundle b){super.onCreate(b);store=new BatchStore(this);template=new TemplateStore(this).get();LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(14,16,14,24);p.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);p.setBackgroundColor(Color.rgb(237,244,250));p.addView(text("طباعة من أرشيف الدفعات",22));batches=new Spinner(this);p.addView(batches);status=text("اختر دفعة",14);p.addView(status);list=new ListView(this);list.setChoiceMode(ListView.CHOICE_MODE_MULTIPLE);p.addView(list,new LinearLayout.LayoutParams(-1,600));Button preview=new Button(this);preview.setText("تصدير المحدد");preview.setOnClickListener(v->exportSelected());p.addView(preview);Button print=new Button(this);print.setText("طباعة المحدد عبر Android");print.setOnClickListener(v->printSelected());p.addView(print);setContentView(p);UiTheme.apply(this);loadBatches();}
 private void loadBatches(){try{ArrayList<String> ids=new ArrayList<>();for(String id:store.batchIds())if(!"identity".equals(id))ids.add(id);batches.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,ids));batches.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>a){}public void onItemSelected(android.widget.AdapterView<?>a,View v,int p,long id){loadCards(ids.get(p));}});if(!ids.isEmpty())loadCards(ids.get(0));else status.setText("لا توجد دفعات محفوظة للطباعة");}catch(Exception e){status.setText("تعذر قراءة الأرشيف دون حذفه");}}
 private void loadCards(String id){try{cards.clear();String raw=store.loadBatch(id);for(String l:(raw==null?"":raw).split("\\n")){String[]x=l.split("\\|",-1);if(x.length==4)cards.add(new String[]{x[0],x[1],x[2]});}ArrayList<String> labels=new ArrayList<>();for(String[] c:cards)labels.add(c[0]+" | "+c[2]);list.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_multiple_choice,labels));status.setText("الكروت: "+cards.size());}catch(Exception e){status.setText("تعذر قراءة الدفعة");}}
 private void exportSelected(){ArrayList<String[]> chosen=new ArrayList<>();for(int i=0;i<cards.size();i++)if(list.isItemChecked(i))chosen.add(cards.get(i));if(chosen.isEmpty()){status.setText("حدد كرتًا واحدًا على الأقل");return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,"selected-vouchers.pdf");selected=new ArrayList<>(chosen);startActivityForResult(i,77);}
 private void printSelected(){ArrayList<String[]> chosen=new ArrayList<>();for(int i=0;i<cards.size();i++)if(list.isItemChecked(i))chosen.add(cards.get(i));if(chosen.isEmpty()){status.setText("حدد كرتًا واحدًا على الأقل");return;}AndroidPrintService.print(this,"Smart Manager vouchers",chosen,template);}
 private ArrayList<String[]> selected=new ArrayList<>();@Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==77&&c==RESULT_OK&&d!=null&&d.getData()!=null&&!selected.isEmpty())try{PdfService.write(this,d.getData(),new ArrayList<>(selected),template);status.setText("تم تصدير المحدد");}catch(Exception e){status.setText("فشل التصدير");}}
 private TextView text(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.rgb(22,47,80));t.setPadding(8,10,8,10);return t;}}
